// Mock tracks module for WooCommerce Blocks
// This is a temporary fix for missing @woocommerce/tracks module

export const recordEvent = (eventName, properties = {}) => {
  // Mock implementation - does nothing in development
  if (process.env.NODE_ENV === 'development') {
    console.log('Mock tracks event:', eventName, properties);
  }
};

export const recordPageView = (pageName, properties = {}) => {
  // Mock implementation - does nothing in development
  if (process.env.NODE_ENV === 'development') {
    console.log('Mock tracks page view:', pageName, properties);
  }
};

export default {
  recordEvent,
  recordPageView,
};
